create function pg_temp.jreg(n integer,op integer,token integer) returns jsonb language sql as $$
 select public.trip_source_execution_register(pg_temp.cid(op),pg_temp.cid(n),1,pg_temp.cid(500),pg_temp.cid(600),repeat('b',64),pg_temp.cid(token),'PNG_STATIC_RGB8_RGBA8_V1','526b66b7bd63daeed309c3d2630cdeaec759a6031a9efe7ade381c06fd04ede5') $$;
create function pg_temp.jclaim(n integer,f bigint,owner integer) returns jsonb language sql as $$ select public.trip_source_execution_claim(pg_temp.cid(n),f,pg_temp.cid(owner)) $$;
create function pg_temp.jattach(n integer,f bigint,owner integer,token integer,c text default repeat('a',64)) returns jsonb language sql as $$ select public.trip_source_execution_attach(pg_temp.cid(n),pg_temp.cid(owner),f,pg_temp.cid(600),pg_temp.cid(token),c) $$;
create function pg_temp.jphase(n integer,f bigint,owner integer,p text) returns jsonb language sql as $$ select public.trip_source_execution_advance(pg_temp.cid(n),pg_temp.cid(owner),f,p) $$;
create function pg_temp.jterminal(n integer,f bigint,owner integer,token integer,c text default repeat('a',64)) returns jsonb language sql as $$ select public.trip_source_execution_terminal(pg_temp.cid(n),pg_temp.cid(owner),f,pg_temp.cid(600),pg_temp.cid(token),c,clock_timestamp(),repeat('d',64),'PARSER_TIMEOUT') $$;
create function pg_temp.jrelease(n integer,f bigint,owner integer) returns jsonb language sql as $$ select public.trip_source_execution_release(pg_temp.cid(n),pg_temp.cid(owner),f) $$;
reset role;grant usage on schema extensions to otr_trip_source_execution_gateway,otr_trip_source_execution_writer;grant otr_trip_source_execution_gateway to otr_trip_source_command_gateway with inherit false,set true;
reset role;set session authorization otr_trip_source_command_gateway;set local role otr_trip_source_execution_gateway;
select throws_ok($q$select pg_temp.jreg(999,23,701)$q$,'P0001','SOURCE_EXECUTION_OPERATION_CONFLICT','registration rejects changed exact attempt');
select throws_ok($q$select pg_temp.jreg(231,999,701)$q$,'P0001','SOURCE_EXECUTION_OPERATION_CONFLICT','registration rejects unknown operation');
select throws_ok($q$select public.trip_source_execution_register(pg_temp.cid(23),pg_temp.cid(231),2,pg_temp.cid(500),pg_temp.cid(600),repeat('b',64),pg_temp.cid(701),'PNG_STATIC_RGB8_RGBA8_V1','526b66b7bd63daeed309c3d2630cdeaec759a6031a9efe7ade381c06fd04ede5')$q$,'P0001','SOURCE_EXECUTION_OPERATION_CONFLICT','registration rejects changed canonical generation');
select is(pg_temp.jreg(231,23,701)->>'phase','STARTING','durable registration before staging');
select is(pg_temp.jreg(331,33,702)->>'phase','UNKNOWN','same byte resource has second protected reference');
select throws_ok($q$select pg_temp.jreg(231,23,701)$q$,'23505',null,'duplicate exact admission cannot allocate parallel attempt');
select is(jsonb_array_length(public.trip_source_execution_inventory()),2,'inventory contains STARTING/UNKNOWN without runtime identity');
select ok((public.trip_source_execution_inventory()->0) ? 'staged_resource','inventory includes exact durable node/key/hash/count');
select is(pg_temp.jclaim(231,0,901)->>'owner_fence','1','first claim fence 0 to 1');
select throws_ok($q$select pg_temp.jclaim(231,0,902)$q$,'P0001','SOURCE_EXECUTION_FENCE_CONFLICT','duplicate claim fails');
select throws_ok($q$select pg_temp.jterminal(231,1,901,701)$q$,'P0001','SOURCE_EXECUTION_PROOF_CONFLICT','missing exact runtime identity cannot prove terminality');
select throws_ok($q$select pg_temp.jrelease(231,1,901)$q$,'P0001','SOURCE_STAGE_PROTECTED','STARTING blocks cleanup');
