select is(pg_temp.jphase(231,1,901,'RUNNING')->>'phase','RUNNING','exact owned STARTING to RUNNING');
select is(public.trip_source_execution_inventory()->0->>'phase','RUNNING','RUNNING retained in recovery inventory');
savepoint owner_rollback;
select is(pg_temp.jclaim(231,1,902)->>'owner_fence','2','takeover advances fence');
rollback to owner_rollback;
select is(public.trip_source_execution_inventory()->0->>'owner_fence','1','rollback preserves prior owner fence');
select is(pg_temp.jphase(231,1,901,'TERMINATION_REQUIRED')->>'phase','TERMINATION_REQUIRED','durable termination responsibility before UNKNOWN');
